-- Server-owned competitive sets for VS random teams. Keeping the roll inside the
-- database prevents clients from disguising arbitrary builds as curated ones.

CREATE TABLE IF NOT EXISTS public.vs_competitive_builds (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  pokemon_id INTEGER NOT NULL REFERENCES public.pokemon(id) ON DELETE CASCADE,
  format TEXT NOT NULL,
  build_name TEXT NOT NULL,
  build JSONB NOT NULL,
  enabled BOOLEAN NOT NULL DEFAULT TRUE,
  UNIQUE (pokemon_id, format, build_name)
);

ALTER TABLE public.vs_competitive_builds ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.vs_competitive_builds FROM PUBLIC, anon, authenticated;

-- BEGIN GENERATED SMOGON POOL
ON CONFLICT (pokemon_id, format, build_name) DO UPDATE SET
  build = EXCLUDED.build,
  enabled = TRUE;
-- END GENERATED SMOGON POOL

CREATE OR REPLACE FUNCTION public.build_random_vs_team(p_format TEXT DEFAULT NULL)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_snapshot JSONB;
  v_format TEXT;
BEGIN
  SELECT available.format INTO v_format
  FROM (
    SELECT builds.format
    FROM public.vs_competitive_builds builds
    WHERE builds.enabled
      AND (p_format IS NULL OR builds.format = p_format)
    GROUP BY builds.format
    HAVING COUNT(DISTINCT builds.pokemon_id) >= 6
    ORDER BY random()
    LIMIT 1
  ) available;

  IF v_format IS NULL THEN
    RAISE EXCEPTION 'The random competitive team pool is unavailable';
  END IF;

  SELECT jsonb_build_object(
    'teamId', 0,
    'name', 'Random Competitive · ' || UPPER(REPLACE(v_format, 'gen9', '')),
    'poolFormat', v_format,
    'members', jsonb_agg(
      jsonb_build_object(
        'pokemonId', rolled.pokemon_id,
        'species', pokemon.name,
        'types', pokemon.types,
        'position', rolled.position,
        'moves', rolled.build->'moves',
        'item', rolled.build->>'item',
        'ability', rolled.build->>'ability',
        'nature', rolled.build->>'nature',
        'evs', rolled.build->'evs',
        'ivs', rolled.build->'ivs',
        'level', 50,
        'isShiny', FALSE,
        'teraType', rolled.build->>'teraType'
      ) ORDER BY rolled.position
    )
  ) INTO v_snapshot
  FROM (
    SELECT selected.*, ROW_NUMBER() OVER (ORDER BY selected.roll)::INTEGER AS position
    FROM (
      SELECT builds.*, random() AS roll
      FROM public.vs_competitive_builds builds
      WHERE builds.enabled AND builds.format = v_format
      ORDER BY roll
      LIMIT 6
    ) selected
  ) rolled
  JOIN public.pokemon pokemon ON pokemon.id = rolled.pokemon_id;

  IF COALESCE(jsonb_array_length(
    CASE
      WHEN jsonb_typeof(v_snapshot->'members') = 'array' THEN v_snapshot->'members'
      ELSE '[]'::JSONB
    END
  ), 0) <> 6 THEN
    RAISE EXCEPTION 'The random competitive team pool is unavailable';
  END IF;

  RETURN v_snapshot;
END;
$$;

CREATE OR REPLACE FUNCTION public.create_random_vs_invite()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_token TEXT;
  v_match public.vs_matches%ROWTYPE;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  v_token := encode(gen_random_bytes(24), 'hex');
  VALUES (
    v_user_id,
    encode(digest(v_token, 'sha256'), 'hex'),
    public.build_random_vs_team()
  )
  RETURNING * INTO v_match;

  RETURN jsonb_build_object(
    'match', to_jsonb(v_match) - 'invite_token_hash',
    'inviteToken', v_token
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.create_random_vs_friend_invite(p_friend_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_host_name TEXT;
  v_result JSONB;
  v_match_id UUID;
  v_token TEXT;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF p_friend_id = v_user_id THEN
    RAISE EXCEPTION 'You cannot challenge yourself';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.friendships friendship
    WHERE friendship.user_id_1 = LEAST(v_user_id, p_friend_id)
      AND friendship.user_id_2 = GREATEST(v_user_id, p_friend_id)
  ) THEN
    RAISE EXCEPTION 'You can only challenge an accepted friend';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.user_presence presence
    WHERE presence.user_id = p_friend_id
      AND presence.last_seen_at >= NOW() - INTERVAL '90 seconds'
  ) THEN
    RAISE EXCEPTION 'That friend is no longer online';
  END IF;

  v_result := public.create_random_vs_invite();
  v_match_id := (v_result->'match'->>'id')::UUID;
  v_token := v_result->>'inviteToken';

  UPDATE public.vs_matches
  SET invited_user_id = p_friend_id, updated_at = NOW()
  WHERE id = v_match_id;
  v_result := jsonb_set(v_result, '{match,invited_user_id}', to_jsonb(p_friend_id), TRUE);

  SELECT COALESCE(
    profile.username,
    host_user.raw_user_meta_data->>'full_name',
    host_user.raw_user_meta_data->>'username',
    split_part(host_user.email, '@', 1),
    'A friend'
  ) INTO v_host_name
  FROM auth.users host_user
  LEFT JOIN public.profiles profile ON profile.id = host_user.id
  WHERE host_user.id = v_user_id;

  VALUES (
    p_friend_id,
    'vs_invite',
    'Battle challenge',
    COALESCE(v_host_name, 'A friend') || ' challenged you to a VS battle',
    '/vs/invite/' || v_token,
    jsonb_build_object(
      'sender_id', v_user_id,
      'sender_name', COALESCE(v_host_name, 'A friend'),
      'match_id', v_match_id
    )
  );

  RETURN v_result;
END;
$$;

CREATE OR REPLACE FUNCTION public.accept_vs_invite_random(p_invite_token TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_match public.vs_matches%ROWTYPE;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT * INTO v_match
  FROM public.vs_matches
  WHERE invite_token_hash = encode(digest(p_invite_token, 'sha256'), 'hex')
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invite not found';
  END IF;
  IF v_match.host_user_id = v_user_id THEN
    RAISE EXCEPTION 'The host cannot accept their own invite';
  END IF;
  IF v_match.invited_user_id IS NOT NULL AND v_match.invited_user_id <> v_user_id THEN
    RAISE EXCEPTION 'This invitation was sent to another trainer';
  END IF;
  IF v_match.status <> 'invited' OR v_match.guest_user_id IS NOT NULL THEN
    RAISE EXCEPTION 'Invite is no longer available';
  END IF;
  IF v_match.invite_expires_at <= NOW() THEN
    UPDATE public.vs_matches SET status = 'expired', updated_at = NOW() WHERE id = v_match.id;
    RAISE EXCEPTION 'Invite has expired';
  END IF;

  UPDATE public.vs_matches
  SET guest_user_id = v_user_id,
      guest_team_snapshot = public.build_random_vs_team(
        CASE
          WHEN v_match.host_team_snapshot->>'teamId' = '0'
            THEN v_match.host_team_snapshot->>'poolFormat'
          ELSE NULL
        END
      ),
      status = 'lobby',
      updated_at = NOW()
  WHERE id = v_match.id
  RETURNING * INTO v_match;

  RETURN to_jsonb(v_match) - 'invite_token_hash';
END;
$$;

REVOKE ALL ON FUNCTION public.build_random_vs_team(TEXT) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.create_random_vs_invite() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.create_random_vs_friend_invite(UUID) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.accept_vs_invite_random(TEXT) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION public.create_random_vs_invite() TO authenticated;
GRANT EXECUTE ON FUNCTION public.create_random_vs_friend_invite(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION public.accept_vs_invite_random(TEXT) TO authenticated;
